//! Trusted TSAs (copied from the Clavis TSA registry, 2026-10-11): public self-signed roots and the
//! TSTInfo policies each TSA signs under. A root changes only when a TSA moves to a new root; the
//! old root then stays listed.

pub struct TsaEntry {
    pub id: &'static str,
    pub policies: &'static [&'static str],
    /// Root certificates, Base64 DER.
    pub roots: &'static [&'static str],
}

pub const REGISTRY: &[TsaEntry] = &[
    TsaEntry {
        id: "sectigo-qualified",
        policies: &["0.4.0.2023.1.1"],
        roots: &[
            "",
        ],
    },
    TsaEntry {
        id: "digicert",
        policies: &["2.16.840.1.114412.7.1"],
        roots: &[
            "",
        ],
    },
];
